-- A1-1.3 候选落库（由 merge_candidates.py 生成）
begin;
create temp table _kbpar(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kbpar(node_id, blocks, search_text) values
(48, $kbpar$[{"t":"list","id":"a1-1-3-1-b1","imp":"normal","items":["1、PC 机组成：主板（芯片组、BIOS、CMOS、PCI 插槽等）、机箱电源、CPU、内存条、声卡、网卡、显卡、插头（插座接口）、输入设备、输出设备（显示器、打印机、音箱/耳机）、外存（硬盘、软驱、光驱、移动硬盘、U 盘等）等。","为了便于不同 PC 机主板的互换，主板的物理尺寸已经标准化，目前使用的比较多的是 ATX 规格的主板。","2、主板：又称母板。计算机最重要的部件之一。主板一般为矩形电路板，上面安装了组成计算机的主要电路系统，一般有 BIOS 芯片、I/O 控制芯片、键盘和面板控制开关接口、指示灯插接件、扩充插槽、主板及插卡的直流电源供电接插件等元件。","3、主板的作用：安装所有电子器件、电路与连接件。","4、芯片组：是主板电路的核心部件，集中了几乎主板上所有控制功能。","5、芯片组是 PC 机各组成部分相互连接和通信的枢纽，实现了系统总线功能。","6、芯片组决定主板能安装的 CPU 的类型、主频。","7、芯片组决定主板能安装的主存的最大容量、速度和使用效率等指标。","8、芯片组是由南桥芯片和北桥芯片构成，一般芯片组的结构图如下所示："],"title":"","ordered":false},{"t":"img","id":"a1-1-3-1-b2","imp":"normal","src":"/kb-assets/theory/p10_r0_0d4a147031da44c2.png","w":1228,"h":728,"title":"典型主板芯片组架构：北桥连接 CPU、内存与显卡，南桥连接 I/O 外设"},{"t":"list","id":"a1-1-3-1-b3","imp":"normal","items":["9、南桥芯片功能：","（1）I/O 控制中心","（2）主要与 PCI 总线槽、USB 接口、硬盘接口、音频解码器、BIOS 和 CMOS 存储器等连接，并借助 Super I/O 芯片提供对鼠标键盘、串行口、并行口等的控制。","10、北桥芯片功能（目前大部功能都集成到 CPU 芯片中处理）：","（1）存储控制中心","（2）高速连接 CPU、存储器、显卡，并且是连接南桥芯片的枢纽","11、现在很多 I/O 控制器都不以扩展卡的形式出现。南桥芯片中已经集成了 I/O 控制器的功能。","12、BIOS：","（1）BIOS：Basic Input/Output System，即“基本输入/输出系统”，存放在主板上只读存储器（ROM）芯片中的一组机器语言程序（固件，二进制语言程序，属于系统软件）。","（2）特点：断电后保存的信息不会消失","（3）功能作用：①开机时诊断计算机故障（比如出现蓝屏）；②启动计算机工作；③启动阶段控制外设基本输入输出操作（键盘、鼠标、磁盘读写、屏幕显示等）。"],"title":"","ordered":false},{"t":"list","id":"a1-1-3-1-b6","imp":"normal","items":["13、内存储器：","（1）计算机存储器分为两类：内存储器和外存储器。","（2）内存和外存的区别：","①、内存存取速度快、容量小、成本高，大都是易失性存储器（临时存放正在运行的程序和数据）；外存存取速度慢，容量大，成本低，断电后信息不会丢失（文件长久存放系统中）。","②、内存都是由半导体芯片构成的；外存的存储介质有：磁表面存储器（硬盘），半导体芯片（U 盘）。","③、内存按字节编址和存取；外存按数据块编址来存取。","④、内存直接与 CPU 连接，CPU（指令）可以对内存中指令及数据进行读、写操作；外存不与 CPU 直接连接，外存中的程序及相关数据需要先传递至内存中后才能被 CPU 使用。","（3）内存容量：内存容量的大小对 CPU 的速度几乎不存在影响，内存容量大小是计算机性能的指标之一。单位：MB 或 GB。","（4）存取时间：从 CPU 送出内存单元的地址码开始，到主存读出数据并送到 CPU（或者是把 CPU 数据写入主存）所需要的时间（单位：ns（纳秒），1 ns = 10⁻⁹ s）。","14、主板的组成部件：主板又称母板，通常安装有CPU插座、CPU调压器、芯片组、第2级高速缓存（有的已做在CPU中）、存储器插槽（SIMM或DIMM）、总线插槽（如PCI-E、AGP）、接口（IDE并口、SATA）、ROM BIOS、时钟/CMOS、电池、超级I/O芯片等。","15、芯片组决定主板能安装的主存的最大容量、速度和可使用的内存条的类型。","16、芯片组与 BIOS 的补充说明：芯片组与 CPU 芯片同步发展，有什么样功能和速度的 CPU，就有什么样的芯片组与之配套。由于集成电路集成度越来越高，为降低系统成本，芯片组中集成了越来越多的功能，包括网卡、显卡、声卡等功能。由于 CPU 芯片越来越复杂、功能越来越强大（如 Core i3/i5/i7），有些已将北桥芯片的存储器控制器和图形控制器功能集成在 CPU 芯片之中，因此主板上北桥芯片已经消失，只需一块南桥芯片即可。","17、内存容量是计算机的性能指标：内存容量属于计算机的性能指标之一，会影响计算机性能。一般所说的“存储容量是计算机的性能指标”，这里的存储容量指的就是内存容量。","18、内存容量及其影响因素：容量以MB为单位，指所有存储单元的总数。 存储单元：每个存储单元就是一个字节、一个地址，CPU访问内存就是寻址，内存存储单元的基本单位是字节。 内存容量主要受主板芯片组、内存插槽及CPU地址总线宽度（位数）的影响。 CPU可寻址空间的大小由地址线宽度决定。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-3-1-b4","imp":"core","kind":"tip","text":"现代主流 Intel 和 AMD 处理器已将传统北桥芯片的==内存控制器（IMC）和 PCI-E 图形控制器直接完全集成在 CPU 芯片内部==，主板仅保留单芯片 PCH（平台控制器中心，即南桥演进），负责管理 SATA、USB、板载声卡网卡与低速总线通道。","title":"考向复习提示：主板芯片组架构演进趋势"},{"t":"callout","id":"a1-1-3-1-b5","imp":"core","kind":"trap","text":"专转本必考概念辨析：==BIOS 是固化在只读存储器（ROM/Flash ROM）中的一组固件系统软件==（包含 POST 加电自检、系统初始化与引导程序）；而 ==CMOS 是随机存取存储器（RAM）==，仅用于存储时间与硬件配置参数，需纽扣电池供电，断电数据丢失；切勿混淆两者的介质类型与功能！","title":"高频易错陷阱：BIOS 与 CMOS 的本质区别"}]$kbpar$::jsonb, $kbpars$1、PC 机组成：主板（芯片组、BIOS、CMOS、PCI 插槽等）、机箱电源、CPU、内存条、声卡、网卡、显卡、插头（插座接口）、输入设备、输出设备（显示器、打印机、音箱/耳机）、外存（硬盘、软驱、光驱、移动硬盘、U 盘等）等。 为了便于不同 PC 机主板的互换，主板的物理尺寸已经标准化，目前使用的比较多的是 ATX 规格的主板。 2、主板：又称母板。计算机最重要的部件之一。主板一般为矩形电路板，上面安装了组成计算机的主要电路系统，一般有 BIOS 芯片、I/O 控制芯片、键盘和面板控制开关接口、指示灯插接件、扩充插槽、主板及插卡的直流电源供电接插件等元件。 3、主板的作用：安装所有电子器件、电路与连接件。 4、芯片组：是主板电路的核心部件，集中了几乎主板上所有控制功能。 5、芯片组是 PC 机各组成部分相互连接和通信的枢纽，实现了系统总线功能。 6、芯片组决定主板能安装的 CPU 的类型、主频。 7、芯片组决定主板能安装的主存的最大容量、速度和使用效率等指标。 8、芯片组是由南桥芯片和北桥芯片构成，一般芯片组的结构图如下所示： 9、南桥芯片功能： （1）I/O 控制中心 （2）主要与 PCI 总线槽、USB 接口、硬盘接口、音频解码器、BIOS 和 CMOS 存储器等连接，并借助 Super I/O 芯片提供对鼠标键盘、串行口、并行口等的控制。 10、北桥芯片功能（目前大部功能都集成到 CPU 芯片中处理）： （1）存储控制中心 （2）高速连接 CPU、存储器、显卡，并且是连接南桥芯片的枢纽 11、现在很多 I/O 控制器都不以扩展卡的形式出现。南桥芯片中已经集成了 I/O 控制器的功能。 12、BIOS： （1）BIOS：Basic Input/Output System，即“基本输入/输出系统”，存放在主板上只读存储器（ROM）芯片中的一组机器语言程序（固件，二进制语言程序，属于系统软件）。 （2）特点：断电后保存的信息不会消失 （3）功能作用：①开机时诊断计算机故障（比如出现蓝屏）；②启动计算机工作；③启动阶段控制外设基本输入输出操作（键盘、鼠标、磁盘读写、屏幕显示等）。 13、内存储器： （1）计算机存储器分为两类：内存储器和外存储器。 （2）内存和外存的区别： ①、内存存取速度快、容量小、成本高，大都是易失性存储器（临时存放正在运行的程序和数据）；外存存取速度慢，容量大，成本低，断电后信息不会丢失（文件长久存放系统中）。 ②、内存都是由半导体芯片构成的；外存的存储介质有：磁表面存储器（硬盘），半导体芯片（U 盘）。 ③、内存按字节编址和存取；外存按数据块编址来存取。 ④、内存直接与 CPU 连接，CPU（指令）可以对内存中指令及数据进行读、写操作；外存不与 CPU 直接连接，外存中的程序及相关数据需要先传递至内存中后才能被 CPU 使用。 （3）内存容量：内存容量的大小对 CPU 的速度几乎不存在影响，内存容量大小是计算机性能的指标之一。单位：MB 或 GB。 （4）存取时间：从 CPU 送出内存单元的地址码开始，到主存读出数据并送到 CPU（或者是把 CPU 数据写入主存）所需要的时间（单位：ns（纳秒），1 ns = 10⁻⁹ s）。 14、主板的组成部件：主板又称母板，通常安装有CPU插座、CPU调压器、芯片组、第2级高速缓存（有的已做在CPU中）、存储器插槽（SIMM或DIMM）、总线插槽（如PCI-E、AGP）、接口（IDE并口、SATA）、ROM BIOS、时钟/CMOS、电池、超级I/O芯片等。 15、芯片组决定主板能安装的主存的最大容量、速度和可使用的内存条的类型。 16、芯片组与 BIOS 的补充说明：芯片组与 CPU 芯片同步发展，有什么样功能和速度的 CPU，就有什么样的芯片组与之配套。由于集成电路集成度越来越高，为降低系统成本，芯片组中集成了越来越多的功能，包括网卡、显卡、声卡等功能。由于 CPU 芯片越来越复杂、功能越来越强大（如 Core i3/i5/i7），有些已将北桥芯片的存储器控制器和图形控制器功能集成在 CPU 芯片之中，因此主板上北桥芯片已经消失，只需一块南桥芯片即可。 17、内存容量是计算机的性能指标：内存容量属于计算机的性能指标之一，会影响计算机性能。一般所说的“存储容量是计算机的性能指标”，这里的存储容量指的就是内存容量。 18、内存容量及其影响因素：容量以MB为单位，指所有存储单元的总数。 存储单元：每个存储单元就是一个字节、一个地址，CPU访问内存就是寻址，内存存储单元的基本单位是字节。 内存容量主要受主板芯片组、内存插槽及CPU地址总线宽度（位数）的影响。 CPU可寻址空间的大小由地址线宽度决定。 考向复习提示：主板芯片组架构演进趋势 现代主流 Intel 和 AMD 处理器已将传统北桥芯片的内存控制器（IMC）和 PCI-E 图形控制器直接完全集成在 CPU 芯片内部，主板仅保留单芯片 PCH（平台控制器中心，即南桥演进），负责管理 SATA、USB、板载声卡网卡与低速总线通道。 高频易错陷阱：BIOS 与 CMOS 的本质区别 专转本必考概念辨析：BIOS 是固化在只读存储器（ROM/Flash ROM）中的一组固件系统软件（包含 POST 加电自检、系统初始化与引导程序）；而 CMOS 是随机存取存储器（RAM），仅用于存储时间与硬件配置参数，需纽扣电池供电，断电数据丢失；切勿混淆两者的介质类型与功能！$kbpars$),(49, $kbpar$[{"t":"list","id":"a1-1-3-2-b1","imp":"normal","items":["1、BIOS 组成及运行过程：","（1）BIOS 组成：","①加电自检程序（POST）：检测计算机硬件故障","②系统自举程序（Boot）：启动计算机，加载并进入操作系统运行态","③CMOS 设置程序：设置系统参数（日期、时间、口令等）。存储的信息包括：系统日期和时间，系统的口令，系统中安装的硬盘、光盘驱动器的数目、类型及参数，显示卡的类型，加载操作系统时访问辅助存储器的顺序等。","④常用（基本）外部设备的驱动程序：在计算机启动阶段实现对键盘、显示器、软驱和硬盘等常用外部设备输入输出操作的控制。","（2）计算机启动顺序：POST→引导装入程序（自举程序）→引导程序→操作系统。若在启动过程中，用户按某一热键（通常是 Del 键），则进入 CMOS 设置程序→系统自举程序→引导程序。","计算机通电后，不能正常启动，可能的原因有：①CMOS 参数被修改，尤其是硬盘参数被改动；②硬盘引导区被破坏，出现无引导盘的信息；③操作系统软件遭到破坏；④硬盘已坏，无法读取信息；等等。","2、CMOS：","（1）CMOS：互补金属氧化物半导体","（2）CMOS 芯片是主板上的一块 RAM（随机存取存储器）。","（3）CMOS 存放计算机一些基本参数（日期、时间、硬件启动顺序等），可以被修改。","（4）通过 BIOS 设置程序对 CMOS 参数进行设置与修改。","（5）断电后 CMOS 中的信息会丢失，所以 CMOS 芯片须由主板上的电池供电，来保证其在计算机断电后信息不会丢失。","3、半导体存储器：","（1）分类：RAM（随机存储器，易失性）和 ROM（只读存储器，非易失性）。","（2）随机存储器（RAM）：属于易失性存储器，一般分为 SRAM（静态随机存储器）和 DRAM（动态随机存储器）。","①、SRAM：易失性，不需要刷新，读写速度较快，电路相对复杂，集成度低，能耗高，成本较高。","②、DRAM：易失性，每 10~100ms 刷新一次，读写速度较慢，电路相对简单，集成度高，能耗低，成本较低。"],"title":"","ordered":false},{"t":"table","id":"a1-1-3-2-t1","imp":"normal","headers":["存储器","速度","成本","是否刷新","电路复杂度","集成度","能耗","应用场景"],"rows":[["SRAM","较快","较高","不刷新","相对复杂","低","高","Cache 存储器"],["DRAM","较慢","较低","10~100ms 刷新一次","相对简单","高","低","主存（内存条）"]],"title":"SRAM 与 DRAM 性能对比表"},{"t":"list","id":"a1-1-3-2-b2","imp":"normal","items":["（3）只读存储器（ROM）：掩模式 ROM、PROM、EPROM、EEPROM（带电可擦可编程只读存储器）和 Flash ROM（闪存）。","①、掩模式 ROM：即 MROM。掩模式只读存储器的内容是由半导体制造厂按用户提出的要求在芯片的生产过程直接写入的，写入之后任何人都无法改变其内容。","②、PROM：可编程只读存储器（Programmable ROM），是可由用户一次性写入信息的只读存储器，是在 MROM（掩模式 ROM）的基础上发展而来的。","③、EPROM 指的是“可擦写可编程只读存储器”，即 Erasable Programmable Read-Only Memory。它的特点是具有可擦除功能，擦除后即可进行再编程，但是缺点是擦除需要使用紫外线照射一定的时间。","④、EEPROM：带电可擦可编程只读存储器，非易失性存储器，断电后信息不会丢失，速度较慢，容量不大，价格便宜，在低端产品中用的较多。","⑤、Flash ROM：称为闪存，快闪存储器，非易失性存储器，断电后信息不会丢失，高电压可写，低电压可读。或非型（NOR）flash，可以用作内存储器（例如存储 BIOS 程序的 flash 存储器）；与非型（NAND）flash，可以用于数码相机存储卡、固态硬盘、U 盘，智能手机中“机身存储或手机存储”等。"],"title":"","ordered":false},{"t":"img","id":"a1-1-3-2-b3","imp":"normal","src":"/kb-assets/theory/p12_r1_3112a1f6861ffe8b.png","w":1398,"h":546,"title":"计算机存储器层次结构：寄存器、Cache、主存、外存与后备存储"},{"t":"list","id":"a1-1-3-2-b6","imp":"normal","items":["4、计算机存储器的层次结构：","（1）速度（快→慢）：寄存器→Cache→主存→外存（硬盘、光盘、U 盘等）→后备存储（磁带库、光盘库等）","（2）速度越快，成本较高。为了获得好的性能/价格比，计算机中各种存储器组成一个层状的塔式结构，取长补短，协调工作。计算机存储器采用多层次塔状结构的目的是解决容量、价格和速度三者之间的矛盾。","（3）工作过程：","①、CPU 运行时，需要的操作数大部分来自寄存器；","②、如需要从（向）存储器中取（存）数据时，先访问 cache（缓存），如在，取自 cache（缓存）；","③、如操作数不在 cache，则访问 RAM（DRAM 即内存），如在 RAM（DRAM 即内存）中，则取自 RAM；","④、如操作数不在 RAM（DRAM 即内存），则访问硬盘，操作数从硬盘中读出→RAM（DRAM 即内存）→cache（缓存）。","5、BIOS（基本输入/输出系统）","（1）BIOS：Basic Input/Output System，即“基本输入/输出系统”，存放在主板上只读存储器（ROM）芯片中的一组机器语言程序（固件，二进制语言程序，属于系统软件）。","（2）特点：断电后保存的信息不会消失","（3）功能作用：","①开机时诊断计算机故障（比如出现蓝屏）","②启动计算机工作","③启动阶段控制外设基本输入输出操作（键盘、鼠标、磁盘读写、屏幕显示等）","④常用外部设备的驱动程序：启动阶段对基本外设输入输出操作","（5）计算机启动顺序：POST->引导装入程序（自举程序）->引导程序->操作系统。","（6）CMOS 中存储的是硬件设置参数：CMOS 中存储的是用户对计算机硬件的设置参数，一般添加新硬件或优化开机时才设置 CMOS。在 CMOS 中可以设置系统时间、启动顺序、病毒检测、即插即用设备、开机密码及 CMOS 密码、磁盘驱动器数量等。","（1）计算机存储器分为两类：内存储器和外存储器。","（2）内存和外存的区别：","①、内存存取速度快、容量小、成本高，大都是易失性存储器（临时存放正在运行的程序和数据）；外存存取速度慢，容量大，成本低，断电后信息不会丢失（文件长久存放系统中）。","②、内存都是由半导体芯片构成的；外存的存储介质有：磁表面存储器（硬盘），半导体芯片（U 盘）。","③、内存按字节编址和存取；外存按数据块编址和存取。","④、内存直接与CPU 连接，CPU（指令）可以对内存中指令及数据进行读、写操作；外存不与CPU 直接连接，外存中的程序及相关数据需要先传递至内存中后才能被CPU 使用。","（3）内存容量：内存容量的大小对 CPU 的运算速度几乎没有直接影响，内存容量大小是计算机性能的重要指标之一，常用单位：MB 或 GB。","（4）存取时间：从CPU 送出内存单元的地址码开始，到主存读出数据并送到CPU（或者是把CPU 数据写入主存）所需要的时间（单位：ns（纳秒），1 ns = \\(10^{-9}\\) s）。","②、Flash ROM（闪速存储器）：非易失性存储器，断电后信息不会丢失，高电压可写、低电压可读；分为或非型（NOR Flash）与非型（NAND Flash）两大类：","NOR Flash 可用作内存储器（如主板存放 BIOS 程序的闪存芯片）；NAND Flash 用于数码相机存储卡、固态硬盘 SSD、U 盘及智能手机“机身存储（ROM）”等。","6、内存容量与存储器速度排序：PC 机中用户实际可用的内存容量通常指 RAM 的容量。 RAM 能够直接与外存交换数据。 计算机中存储器速度由快到慢：CPU → 寄存器 → Cache → 内存 → 外存储器（软盘、硬盘、光盘）→ 后备存储器（磁带库、光盘库）。","7、存储器的层次结构与工作过程","（1）速度越快，成本较高。 为了获得好的性能/价格比，计算机中各种存储器组成一个层状的塔式结构，取长补短，协调工作。","③、如操作数不在Cache，则访问RAM，如在RAM 中，则取自RAM","8、PC 机硬件组成与主板结构：PC 机由主板（芯片组、BIOS、CMOS、PCI/PCIe 插槽等）、机箱电源、CPU、内存条、显卡/声卡/网卡、输入输出设备及外存（硬盘、光驱、U 盘等）构成；为便于主板互换，主板物理尺寸已标准化，目前主流使用 ATX 规格主板。主板又称母板，是集成 BIOS 芯片、I/O 控制芯片、面板开关/指示灯接插件、扩充插槽及直流供电接插件的矩形电路板，是系统总线功能的枢纽。","9、主板芯片组（Chipset）及南北桥分工：芯片组是主板各部件相互连接与通信的枢纽，决定了主板所能安装的 CPU 类型、主频及支持的最大内存容量；传统主板芯片组由北桥与南桥组成：","（1）北桥芯片（MCH）：存储控制中心，负责高速连接 CPU、内存控制器、显卡接口并枢纽连接南桥芯片；现代架构中北桥核心功能（内存控制器、PCIe 控制器等）已大多集成进 CPU 芯片内部。","（2）南桥芯片（ICH）：I/O 控制中心，负责连接 PCI 总线插槽、USB 接口、硬盘接口（SATA）、音频编解码器、网卡、BIOS 与 CMOS 存储器，并借助 Super I/O 芯片控制鼠标、键盘、串口和并口；当前多数 I/O 控制器功能已集成入南桥（PCH）。","10、CMOS 参数与 BIOS 启动热键流程：BIOS 中的 CMOS 设置程序用于设定系统日期、时间、开机口令、磁盘驱动器数量与类型、显卡及引导设备启动顺序；正常冷启动顺序为：POST（加电自检）→ 系统自举程序（Boot）→ 引导程序 → 操作系统；若在自检阶段按下热键（通常为 `Del` 或 `F2`），则执行按 `Del` 键 → 进入 CMOS 设置程序 → 保存后交由系统自举程序 → 引导程序 → 操作系统。","11、DRAM 主存储器与内存条：主存储器主要由 DRAM 芯片组成，包含大量存储单元，每个存储单元可以存放 1 个字节（8 个二进制位）。存储器的存储容量就是它所包含的存储单元的总和。每个存储单元都有一个地址，CPU 按地址对存储器进行访问。 存储器的存取时间指从 CPU 给出存储器地址开始，到存储器读出数据并送到 CPU（或把 CPU 的数据写入存储器）所需要的时间，主存储器存取时间的单位是 ns（1 ns = \\(10^{-9}\\) 秒）。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-3-2-b4","imp":"core","kind":"tip","text":"内存储器两大核心：==RAM（SRAM 用于 Cache 速度快成本高；DRAM 用于主存需动态刷新）==；==ROM（Mask ROM、PROM、EPROM、EEPROM/Flash ROM）==；计算机开机流程：加电→==CPU 执行 BIOS 中的 POST 加电自检==→初始化设备→加载引导扇区（MBR/GPT）→将 OS 内核载入内存启动。","title":"考向复习提示：RAM 与 ROM 各种类型及开机流程"},{"t":"callout","id":"a1-1-3-2-b5","imp":"core","kind":"trap","text":"==SRAM 依靠双稳态触发器存储信息==，只要通电信息不丢失，不需刷新；而 ==DRAM 依靠微型电容上的电荷存储信息==，电容存在漏电现象，电荷会在数毫秒内自然漏掉，因此==必须由内存控制器每隔数毫秒定期执行动态刷新（充电）操作==；考试常考混淆两者的内部结构与是否需要刷新。","title":"高频易错陷阱：DRAM 为什么必须定期刷新？"}]$kbpar$::jsonb, $kbpars$1、BIOS 组成及运行过程： （1）BIOS 组成： ①加电自检程序（POST）：检测计算机硬件故障 ②系统自举程序（Boot）：启动计算机，加载并进入操作系统运行态 ③CMOS 设置程序：设置系统参数（日期、时间、口令等）。存储的信息包括：系统日期和时间，系统的口令，系统中安装的硬盘、光盘驱动器的数目、类型及参数，显示卡的类型，加载操作系统时访问辅助存储器的顺序等。 ④常用（基本）外部设备的驱动程序：在计算机启动阶段实现对键盘、显示器、软驱和硬盘等常用外部设备输入输出操作的控制。 （2）计算机启动顺序：POST→引导装入程序（自举程序）→引导程序→操作系统。若在启动过程中，用户按某一热键（通常是 Del 键），则进入 CMOS 设置程序→系统自举程序→引导程序。 计算机通电后，不能正常启动，可能的原因有：①CMOS 参数被修改，尤其是硬盘参数被改动；②硬盘引导区被破坏，出现无引导盘的信息；③操作系统软件遭到破坏；④硬盘已坏，无法读取信息；等等。 2、CMOS： （1）CMOS：互补金属氧化物半导体 （2）CMOS 芯片是主板上的一块 RAM（随机存取存储器）。 （3）CMOS 存放计算机一些基本参数（日期、时间、硬件启动顺序等），可以被修改。 （4）通过 BIOS 设置程序对 CMOS 参数进行设置与修改。 （5）断电后 CMOS 中的信息会丢失，所以 CMOS 芯片须由主板上的电池供电，来保证其在计算机断电后信息不会丢失。 3、半导体存储器： （1）分类：RAM（随机存储器，易失性）和 ROM（只读存储器，非易失性）。 （2）随机存储器（RAM）：属于易失性存储器，一般分为 SRAM（静态随机存储器）和 DRAM（动态随机存储器）。 ①、SRAM：易失性，不需要刷新，读写速度较快，电路相对复杂，集成度低，能耗高，成本较高。 ②、DRAM：易失性，每 10~100ms 刷新一次，读写速度较慢，电路相对简单，集成度高，能耗低，成本较低。 SRAM 较快 较高 不刷新 相对复杂 低 高 Cache 存储器 DRAM 较慢 较低 10~100ms 刷新一次 相对简单 高 低 主存（内存条） （3）只读存储器（ROM）：掩模式 ROM、PROM、EPROM、EEPROM（带电可擦可编程只读存储器）和 Flash ROM（闪存）。 ①、掩模式 ROM：即 MROM。掩模式只读存储器的内容是由半导体制造厂按用户提出的要求在芯片的生产过程直接写入的，写入之后任何人都无法改变其内容。 ②、PROM：可编程只读存储器（Programmable ROM），是可由用户一次性写入信息的只读存储器，是在 MROM（掩模式 ROM）的基础上发展而来的。 ③、EPROM 指的是“可擦写可编程只读存储器”，即 Erasable Programmable Read-Only Memory。它的特点是具有可擦除功能，擦除后即可进行再编程，但是缺点是擦除需要使用紫外线照射一定的时间。 ④、EEPROM：带电可擦可编程只读存储器，非易失性存储器，断电后信息不会丢失，速度较慢，容量不大，价格便宜，在低端产品中用的较多。 ⑤、Flash ROM：称为闪存，快闪存储器，非易失性存储器，断电后信息不会丢失，高电压可写，低电压可读。或非型（NOR）flash，可以用作内存储器（例如存储 BIOS 程序的 flash 存储器）；与非型（NAND）flash，可以用于数码相机存储卡、固态硬盘、U 盘，智能手机中“机身存储或手机存储”等。 4、计算机存储器的层次结构： （1）速度（快→慢）：寄存器→Cache→主存→外存（硬盘、光盘、U 盘等）→后备存储（磁带库、光盘库等） （2）速度越快，成本较高。为了获得好的性能/价格比，计算机中各种存储器组成一个层状的塔式结构，取长补短，协调工作。计算机存储器采用多层次塔状结构的目的是解决容量、价格和速度三者之间的矛盾。 （3）工作过程： ①、CPU 运行时，需要的操作数大部分来自寄存器； ②、如需要从（向）存储器中取（存）数据时，先访问 cache（缓存），如在，取自 cache（缓存）； ③、如操作数不在 cache，则访问 RAM（DRAM 即内存），如在 RAM（DRAM 即内存）中，则取自 RAM； ④、如操作数不在 RAM（DRAM 即内存），则访问硬盘，操作数从硬盘中读出→RAM（DRAM 即内存）→cache（缓存）。 5、BIOS（基本输入/输出系统） （1）BIOS：Basic Input/Output System，即“基本输入/输出系统”，存放在主板上只读存储器（ROM）芯片中的一组机器语言程序（固件，二进制语言程序，属于系统软件）。 （2）特点：断电后保存的信息不会消失 （3）功能作用： ①开机时诊断计算机故障（比如出现蓝屏） ②启动计算机工作 ③启动阶段控制外设基本输入输出操作（键盘、鼠标、磁盘读写、屏幕显示等） ④常用外部设备的驱动程序：启动阶段对基本外设输入输出操作 （5）计算机启动顺序：POST->引导装入程序（自举程序）->引导程序->操作系统。 （6）CMOS 中存储的是硬件设置参数：CMOS 中存储的是用户对计算机硬件的设置参数，一般添加新硬件或优化开机时才设置 CMOS。在 CMOS 中可以设置系统时间、启动顺序、病毒检测、即插即用设备、开机密码及 CMOS 密码、磁盘驱动器数量等。 （1）计算机存储器分为两类：内存储器和外存储器。 （2）内存和外存的区别： ①、内存存取速度快、容量小、成本高，大都是易失性存储器（临时存放正在运行的程序和数据）；外存存取速度慢，容量大，成本低，断电后信息不会丢失（文件长久存放系统中）。 ②、内存都是由半导体芯片构成的；外存的存储介质有：磁表面存储器（硬盘），半导体芯片（U 盘）。 ③、内存按字节编址和存取；外存按数据块编址和存取。 ④、内存直接与CPU 连接，CPU（指令）可以对内存中指令及数据进行读、写操作；外存不与CPU 直接连接，外存中的程序及相关数据需要先传递至内存中后才能被CPU 使用。 （3）内存容量：内存容量的大小对 CPU 的运算速度几乎没有直接影响，内存容量大小是计算机性能的重要指标之一，常用单位：MB 或 GB。 （4）存取时间：从CPU 送出内存单元的地址码开始，到主存读出数据并送到CPU（或者是把CPU 数据写入主存）所需要的时间（单位：ns（纳秒），1 ns = \(10^{-9}\) s）。 ②、Flash ROM（闪速存储器）：非易失性存储器，断电后信息不会丢失，高电压可写、低电压可读；分为或非型（NOR Flash）与非型（NAND Flash）两大类： NOR Flash 可用作内存储器（如主板存放 BIOS 程序的闪存芯片）；NAND Flash 用于数码相机存储卡、固态硬盘 SSD、U 盘及智能手机“机身存储（ROM）”等。 6、内存容量与存储器速度排序：PC 机中用户实际可用的内存容量通常指 RAM 的容量。 RAM 能够直接与外存交换数据。 计算机中存储器速度由快到慢：CPU → 寄存器 → Cache → 内存 → 外存储器（软盘、硬盘、光盘）→ 后备存储器（磁带库、光盘库）。 7、存储器的层次结构与工作过程 （1）速度越快，成本较高。 为了获得好的性能/价格比，计算机中各种存储器组成一个层状的塔式结构，取长补短，协调工作。 ③、如操作数不在Cache，则访问RAM，如在RAM 中，则取自RAM 8、PC 机硬件组成与主板结构：PC 机由主板（芯片组、BIOS、CMOS、PCI/PCIe 插槽等）、机箱电源、CPU、内存条、显卡/声卡/网卡、输入输出设备及外存（硬盘、光驱、U 盘等）构成；为便于主板互换，主板物理尺寸已标准化，目前主流使用 ATX 规格主板。主板又称母板，是集成 BIOS 芯片、I/O 控制芯片、面板开关/指示灯接插件、扩充插槽及直流供电接插件的矩形电路板，是系统总线功能的枢纽。 9、主板芯片组（Chipset）及南北桥分工：芯片组是主板各部件相互连接与通信的枢纽，决定了主板所能安装的 CPU 类型、主频及支持的最大内存容量；传统主板芯片组由北桥与南桥组成： （1）北桥芯片（MCH）：存储控制中心，负责高速连接 CPU、内存控制器、显卡接口并枢纽连接南桥芯片；现代架构中北桥核心功能（内存控制器、PCIe 控制器等）已大多集成进 CPU 芯片内部。 （2）南桥芯片（ICH）：I/O 控制中心，负责连接 PCI 总线插槽、USB 接口、硬盘接口（SATA）、音频编解码器、网卡、BIOS 与 CMOS 存储器，并借助 Super I/O 芯片控制鼠标、键盘、串口和并口；当前多数 I/O 控制器功能已集成入南桥（PCH）。 10、CMOS 参数与 BIOS 启动热键流程：BIOS 中的 CMOS 设置程序用于设定系统日期、时间、开机口令、磁盘驱动器数量与类型、显卡及引导设备启动顺序；正常冷启动顺序为：POST（加电自检）→ 系统自举程序（Boot）→ 引导程序 → 操作系统；若在自检阶段按下热键（通常为 `Del` 或 `F2`），则执行按 `Del` 键 → 进入 CMOS 设置程序 → 保存后交由系统自举程序 → 引导程序 → 操作系统。 11、DRAM 主存储器与内存条：主存储器主要由 DRAM 芯片组成，包含大量存储单元，每个存储单元可以存放 1 个字节（8 个二进制位）。存储器的存储容量就是它所包含的存储单元的总和。每个存储单元都有一个地址，CPU 按地址对存储器进行访问。 存储器的存取时间指从 CPU 给出存储器地址开始，到存储器读出数据并送到 CPU（或把 CPU 的数据写入存储器）所需要的时间，主存储器存取时间的单位是 ns（1 ns = \(10^{-9}\) 秒）。 考向复习提示：RAM 与 ROM 各种类型及开机流程 内存储器两大核心：RAM（SRAM 用于 Cache 速度快成本高；DRAM 用于主存需动态刷新）；ROM（Mask ROM、PROM、EPROM、EEPROM/Flash ROM）；计算机开机流程：加电→CPU 执行 BIOS 中的 POST 加电自检→初始化设备→加载引导扇区（MBR/GPT）→将 OS 内核载入内存启动。 高频易错陷阱：DRAM 为什么必须定期刷新？ SRAM 依靠双稳态触发器存储信息，只要通电信息不丢失，不需刷新；而 DRAM 依靠微型电容上的电荷存储信息，电容存在漏电现象，电荷会在数毫秒内自然漏掉，因此必须由内存控制器每隔数毫秒定期执行动态刷新（充电）操作；考试常考混淆两者的内部结构与是否需要刷新。$kbpars$),(50, $kbpar$[{"t":"list","id":"a1-1-3-3-b1","imp":"normal","items":["1、DDR3 和 DDR4：","①、均采用双排直插式，其触点分布在内存条的两面；","②、PC 主板上一般配有两个或四个内存条插槽","2、DDR 内存数据传输率计算：","①、数据传输率即内存带宽，指单位时间内通过内存的数据量，单位以 GB/s 表示。","②、计算公式：公式一：内存带宽=工作频率×位宽/8。","公式二：内存带宽=时钟频率×2^(DDR 代数[DDR 就是 1，DDR2 就是 2，DDR3 就是 3，DDR4 就是 4])×位宽/8。"],"title":"","ordered":false},{"t":"table","id":"a1-1-3-3-t1","imp":"normal","headers":["内存规格","内部时钟频率（MHz）","预取位数（bit）","等效预取倍数","是否采用 Bank Group 技术","外部时钟频率","数据传输率","最高工作频率（MHz）","数据位宽（bit）","计算式 频率×位宽/8（MB/s）","数据传输（内存）带宽"],"rows":[["SDRAM-133","133","1","1","否","133MHz","133MT/s","133","64","1064","1.06GB/s"],["DDR-266","133","2","2","否","133MHz","266MT/s","266","64","2128","2.1GB/s"],["DDR-333","166","2","2","否","166MHz","333MT/s","332","64","2656","2.7GB/s"],["DDR-400","200","2","2","否","200MHz","400MT/s","400","64","3200","3.2GB/s"],["DDR2-533","133","4","4","否","266MHz","533MT/s","532","64","4256","4.2GB/s"],["DDR2-667","166","4","4","否","333MHz","666MT/s","664","64","5312","5.3GB/s"],["DDR2-800","200","4","4","否","400MHz","800MT/s","800","64","6400","6.4GB/s"],["DDR3-1066","133","8","8","否","533MHz","1066MT/s","1064","64","8512","8.5GB/s"],["DDR3-1333","166","8","8","否","667MHz","1333MT/s","1328","64","10624","10.6GB/s"],["DDR3-1600","200","8","8","否","800MHz","1600MT/s","1600","64","12800","12.8GB/s"],["DDR4-2133","133","8","16","是","1066MHz","2133MT/s","2133","64","17064","17.1GB/s"],["DDR4-2666","166","8","16","是","1333MHz","2666MT/s","2666","64","21328","21.3GB/s"],["DDR4-3200","200","8","16","是","1600MHz","3200MT/s","3200","64","25600","25.6GB/s"]],"title":"常见内存规格参数与带宽对照表"},{"t":"list","id":"a1-1-3-3-b2","imp":"normal","items":["外部时钟频率=数据传输率/2","内部时钟频率=数据传输率/DDR 的数据预取位数（等效）","内存带宽（MB/s）=最高工作频率×数据位宽/8"],"title":"","ordered":false},{"t":"list","id":"a1-1-3-3-b3","imp":"normal","items":["3、内存条的封装：目前内存的封装方式主要有 TSOP、BGA、CSP 等三种，封装方式也影响着内存条的性能优劣。"],"title":"","ordered":false},{"t":"list","id":"a1-1-3-3-b4","imp":"normal","items":["4、内存地址：","①、内存中是每一个字节都赋予唯一的编号，称为地址","②、操作系统使用地址对内存进行管理","③、内存的地址从 0 开始编址"],"title":"","ordered":false},{"t":"img","id":"a1-1-3-3-b7","imp":"normal","src":"/kb-assets/theory/p12_r0_bd4485098f4693c6.png","w":312,"h":271,"title":"内存储器按字节编址示意：存储单元地址与存储内容"},{"t":"list","id":"a1-1-3-3-b8","imp":"normal","items":["④、内存寻址范围取决于地址线位数的多少（n），即受地址位数的限制。可寻址空间为 2^n 字节。","公式：末地址-初地址+1=空间，单位是 B（字节）","相关题型：","（1）已知末地址、初始地址（默认是 0），求访问空间，求地址线位（根）数。","例如：末地址是 FFFH，初始地址是 0H，求解如下：","FFFH-0H+1=1000H=2^12=4KB，12 就是地址线根数。","（2）已知访问空间、初始地址是 0H，求末地址。","例如：访问空间是 1KB，初始地址是 0H，求末地址。","末=1KB-1+0H=2^10B-1=10000000000B-1=1111111111B=3FFH","（3）已知访问空间、末地址，求初地址。","已知访问空间，末地址是 4FFH，求初地址。初=末-空间+1=4FFH-400H+1=500H-400H=100H","②、计算公式：\\(\\text{数据传输率（内存带宽）} = \\text{工作频率} \\times \\text{位宽} \\div 8\\)（单位：Byte/s，1 字节 = 8 位，故除以 8 化为字节每秒）。","5、内存容量与存取时间：内存编址单位为B（字节），内存采用连续编址。CPU总线上的信号种类包括地址信号、控制信号和数据信号。 访问内存空间的大小： 最大访问内存空间2的地址线根数次方B。 最大访问内存空间2的最大末地址位数次方B。 例如CPU访问内存，最大末地址为3FFFFFFFH，则CPU能够访问到的最大内存空间为1024MB。 从首地址开始访问到某个地址结束时，访问内存空间地址码十进制值+1B。 存取周期：从上一次存取到下一次存取的时间间隔。 存取时间：从CPU送出地址码后，到内存中取到（存入）数据并送回到CPU所花费的时间。","6、PC机主存储器的物理结构：主存储器由1～4个内存条组成。内存条由若干片DRAM芯片焊装在一小条印制电路板上制成，必须插在主板的内存条插槽中才能使用。 目前流行的是DDR4和DDR3内存条，均采用双列直插式，触点分布在内存条的两面。DDR2和DDR3均有240个引脚，但不可互换使用。PC机主板一般配备2个或4个内存条插槽。","7、SDRAM 与 DDR 内存条的区别：SDRAM通常采用168线的DIMM内存条，DDR、DDR2、DDR3也采用双列直插式DIMM内存条，触点分布在内存条的两面。一个时钟周期内，SDRAM只能传送1次数据，DDR为2次，DDR2为4次，DDR3为8次。","8、存取时间：地址被选定后，读出数据并将数据送入CPU的时间，或CPU向内存写入数据的时间。","9、内存条最大存储容量：若内存条的地址访问线（地址访问位数）为32根，则该内存条的最大存储容量为2的32次方Byte，即4GB。","10、DDR SDRAM 参数与带宽计算：内存有三种不同的频率指标：核心频率（内部时钟频率）、外部时钟频率和有效数据传输率。以标称 `DDR3-1066` 的 64 位内存条为例，其核心频率 \\(133\\text{ MHz}\\)、8 位预取、外部时钟频率 \\(533\\text{ MHz}\\)，最高工作频率 \\(1064\\text{ MHz}\\)，默认带宽为 \\(1064 \\times 64 \\div 8 = 8512\\text{ MB/s} \\approx 8.5\\text{ GB/s}\\)。","11、DDR 频率与带宽核心换算公式：","（1）内存带宽（MB/s）：\\(\\text{最高工作频率（MHz）} \\times \\text{数据位宽（bit）} \\div 8\\)，或利用内部核心时钟频率与预取位数表达为 \\(\\text{内部时钟频率} \\times 2^{\\text{DDR代数}} \\times \\text{位宽} \\div 8\\)（其中 DDR 取 1、DDR2 取 2、DDR3 取 3、DDR4 取 4；DDR4 物理预取仍为 8 bit，依靠 2 个 Bank Group 并行实现等效 16 倍预取）。","（2）外部时钟频率与内部时钟频率公式：\\(\\text{外部时钟频率} = \\text{数据传输率} \\div 2\\)；\\(\\text{内部时钟频率} = \\text{数据传输率} \\div \\text{等效预取位数}\\)。","12、内存地址区间、容量与地址线根数换算（三大高频题型）：地址线位数为 \\(n\\) 时可寻址空间为 \\(2^n\\text{ B}\\)，核心恒等式：\\(\\text{空间容量（B）} = \\text{末地址} - \\text{初地址} + 1\\)。","（1）已知首末地址求容量与地址线根数：设初地址 `0H`、末地址 `FFFH`，则 \\(\\text{空间} = \\text{FFFH} - 0\\text{H} + 1 = 1000\\text{H} = 2^{12}\\text{ B} = 4\\text{ KB} = 4096\\text{ B}\\)，所需地址线为 \\(12\\) 根。","（2）已知初地址与容量求末地址：设访问空间 `1 KB`（\\(2^{10}\\text{ B}\\)）、初地址 `0H`，则 \\(\\text{末地址} = 0\\text{H} + 2^{10} - 1 = 400\\text{H} - 1 = \\text{3FFH}\\)。","（3）已知末地址与容量求初地址：设访问空间 `1 KB`（\\(400\\text{H}\\)）、末地址 `4FFH`，则 \\(\\text{初地址} = \\text{4FFH} - 400\\text{H} + 1 = \\text{100H}\\)。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-3-3-b5","imp":"core","kind":"tip","text":"==内存带宽（Byte/s） = 等效数据传输频率（Hz） × 数据总线位宽（bit） ÷ 8==\n• PC 台式机单根内存条标准数据位宽为 ==64 位（即 8 字节）==；\n• 因此单通道内存带宽简写为：==内存带宽（MB/s） = 等效传输频率（MHz） × 8 字节==；\n• 若开启==双通道内存模式==，总数据位宽翻倍为 128 位，带宽相应乘以 2。","title":"考向复习提示：内存数据传输带宽黄金计算公式"},{"t":"callout","id":"a1-1-3-3-b6","imp":"core","kind":"trap","text":"DDR SDRAM 是在时钟信号的==上升沿和下降沿均传输数据（双倍速率）==；题目中如果给出的是 DDR4-3200，其 3200 是指==等效数据传输频率为 3200 MT/s（或等效 3200 MHz）==，而不是实际核心物理频率（实际核心频率仅为 400 MHz，4 倍预取与双沿传输）；计算带宽时务必使用==等效传输频率 3200==代入公式！","title":"高频易错陷阱：核心工作频率 vs 等效传输频率"},{"t":"callout","id":"a1-1-3-3-p2-sync-tip","imp":"core","kind":"tip","text":"内存带宽计算题仍以考纲经典的 `DDR3` / `DDR4` 公式为准（务必记住 `64` 位单通道位宽为 `8` 字节）；实际硬件架构已全面迭代至：\n• ==DDR5 全面成为主流==：消费级与数据中心服务器已广泛采用 `DDR5`（主流起步迈向 `6400 MT/s` 及以上），并配合 `MCRDIMM`、`RDIMM` 提升高并发访存密度；\n• ==HBM3E 与 HBM4 高带宽内存==：面对大模型千亿参数访存瓶颈，3D 堆叠高带宽内存（`HBM3E`）已成为 AI 加速卡标配；==2025–2026 年新一代 `HBM4` 迈入大规模量产商用==，接口位宽由 `1024-bit` 翻倍至 `2048-bit`，单栈总带宽跃升至每秒数 TB 级。","title":"考向复习提示：2025–2026 前沿同步：DDR5 普及与 AI 核心显存 HBM3E/HBM4"}]$kbpar$::jsonb, $kbpars$1、DDR3 和 DDR4： ①、均采用双排直插式，其触点分布在内存条的两面； ②、PC 主板上一般配有两个或四个内存条插槽 2、DDR 内存数据传输率计算： ①、数据传输率即内存带宽，指单位时间内通过内存的数据量，单位以 GB/s 表示。 ②、计算公式：公式一：内存带宽=工作频率×位宽/8。 公式二：内存带宽=时钟频率×2^(DDR 代数[DDR 就是 1，DDR2 就是 2，DDR3 就是 3，DDR4 就是 4])×位宽/8。 SDRAM-133 133 1 1 否 133MHz 133MT/s 133 64 1064 1.06GB/s DDR-266 133 2 2 否 133MHz 266MT/s 266 64 2128 2.1GB/s DDR-333 166 2 2 否 166MHz 333MT/s 332 64 2656 2.7GB/s DDR-400 200 2 2 否 200MHz 400MT/s 400 64 3200 3.2GB/s DDR2-533 133 4 4 否 266MHz 533MT/s 532 64 4256 4.2GB/s DDR2-667 166 4 4 否 333MHz 666MT/s 664 64 5312 5.3GB/s DDR2-800 200 4 4 否 400MHz 800MT/s 800 64 6400 6.4GB/s DDR3-1066 133 8 8 否 533MHz 1066MT/s 1064 64 8512 8.5GB/s DDR3-1333 166 8 8 否 667MHz 1333MT/s 1328 64 10624 10.6GB/s DDR3-1600 200 8 8 否 800MHz 1600MT/s 1600 64 12800 12.8GB/s DDR4-2133 133 8 16 是 1066MHz 2133MT/s 2133 64 17064 17.1GB/s DDR4-2666 166 8 16 是 1333MHz 2666MT/s 2666 64 21328 21.3GB/s DDR4-3200 200 8 16 是 1600MHz 3200MT/s 3200 64 25600 25.6GB/s 外部时钟频率=数据传输率/2 内部时钟频率=数据传输率/DDR 的数据预取位数（等效） 内存带宽（MB/s）=最高工作频率×数据位宽/8 3、内存条的封装：目前内存的封装方式主要有 TSOP、BGA、CSP 等三种，封装方式也影响着内存条的性能优劣。 4、内存地址： ①、内存中是每一个字节都赋予唯一的编号，称为地址 ②、操作系统使用地址对内存进行管理 ③、内存的地址从 0 开始编址 ④、内存寻址范围取决于地址线位数的多少（n），即受地址位数的限制。可寻址空间为 2^n 字节。 公式：末地址-初地址+1=空间，单位是 B（字节） 相关题型： （1）已知末地址、初始地址（默认是 0），求访问空间，求地址线位（根）数。 例如：末地址是 FFFH，初始地址是 0H，求解如下： FFFH-0H+1=1000H=2^12=4KB，12 就是地址线根数。 （2）已知访问空间、初始地址是 0H，求末地址。 例如：访问空间是 1KB，初始地址是 0H，求末地址。 末=1KB-1+0H=2^10B-1=10000000000B-1=1111111111B=3FFH （3）已知访问空间、末地址，求初地址。 已知访问空间，末地址是 4FFH，求初地址。初=末-空间+1=4FFH-400H+1=500H-400H=100H ②、计算公式：\(\text{数据传输率（内存带宽）} = \text{工作频率} \times \text{位宽} \div 8\)（单位：Byte/s，1 字节 = 8 位，故除以 8 化为字节每秒）。 5、内存容量与存取时间：内存编址单位为B（字节），内存采用连续编址。CPU总线上的信号种类包括地址信号、控制信号和数据信号。 访问内存空间的大小： 最大访问内存空间2的地址线根数次方B。 最大访问内存空间2的最大末地址位数次方B。 例如CPU访问内存，最大末地址为3FFFFFFFH，则CPU能够访问到的最大内存空间为1024MB。 从首地址开始访问到某个地址结束时，访问内存空间地址码十进制值+1B。 存取周期：从上一次存取到下一次存取的时间间隔。 存取时间：从CPU送出地址码后，到内存中取到（存入）数据并送回到CPU所花费的时间。 6、PC机主存储器的物理结构：主存储器由1～4个内存条组成。内存条由若干片DRAM芯片焊装在一小条印制电路板上制成，必须插在主板的内存条插槽中才能使用。 目前流行的是DDR4和DDR3内存条，均采用双列直插式，触点分布在内存条的两面。DDR2和DDR3均有240个引脚，但不可互换使用。PC机主板一般配备2个或4个内存条插槽。 7、SDRAM 与 DDR 内存条的区别：SDRAM通常采用168线的DIMM内存条，DDR、DDR2、DDR3也采用双列直插式DIMM内存条，触点分布在内存条的两面。一个时钟周期内，SDRAM只能传送1次数据，DDR为2次，DDR2为4次，DDR3为8次。 8、存取时间：地址被选定后，读出数据并将数据送入CPU的时间，或CPU向内存写入数据的时间。 9、内存条最大存储容量：若内存条的地址访问线（地址访问位数）为32根，则该内存条的最大存储容量为2的32次方Byte，即4GB。 10、DDR SDRAM 参数与带宽计算：内存有三种不同的频率指标：核心频率（内部时钟频率）、外部时钟频率和有效数据传输率。以标称 `DDR3-1066` 的 64 位内存条为例，其核心频率 \(133\text{ MHz}\)、8 位预取、外部时钟频率 \(533\text{ MHz}\)，最高工作频率 \(1064\text{ MHz}\)，默认带宽为 \(1064 \times 64 \div 8 = 8512\text{ MB/s} \approx 8.5\text{ GB/s}\)。 11、DDR 频率与带宽核心换算公式： （1）内存带宽（MB/s）：\(\text{最高工作频率（MHz）} \times \text{数据位宽（bit）} \div 8\)，或利用内部核心时钟频率与预取位数表达为 \(\text{内部时钟频率} \times 2^{\text{DDR代数}} \times \text{位宽} \div 8\)（其中 DDR 取 1、DDR2 取 2、DDR3 取 3、DDR4 取 4；DDR4 物理预取仍为 8 bit，依靠 2 个 Bank Group 并行实现等效 16 倍预取）。 （2）外部时钟频率与内部时钟频率公式：\(\text{外部时钟频率} = \text{数据传输率} \div 2\)；\(\text{内部时钟频率} = \text{数据传输率} \div \text{等效预取位数}\)。 12、内存地址区间、容量与地址线根数换算（三大高频题型）：地址线位数为 \(n\) 时可寻址空间为 \(2^n\text{ B}\)，核心恒等式：\(\text{空间容量（B）} = \text{末地址} - \text{初地址} + 1\)。 （1）已知首末地址求容量与地址线根数：设初地址 `0H`、末地址 `FFFH`，则 \(\text{空间} = \text{FFFH} - 0\text{H} + 1 = 1000\text{H} = 2^{12}\text{ B} = 4\text{ KB} = 4096\text{ B}\)，所需地址线为 \(12\) 根。 （2）已知初地址与容量求末地址：设访问空间 `1 KB`（\(2^{10}\text{ B}\)）、初地址 `0H`，则 \(\text{末地址} = 0\text{H} + 2^{10} - 1 = 400\text{H} - 1 = \text{3FFH}\)。 （3）已知末地址与容量求初地址：设访问空间 `1 KB`（\(400\text{H}\)）、末地址 `4FFH`，则 \(\text{初地址} = \text{4FFH} - 400\text{H} + 1 = \text{100H}\)。 考向复习提示：内存数据传输带宽黄金计算公式 内存带宽（Byte/s） = 等效数据传输频率（Hz） × 数据总线位宽（bit） ÷ 8 • PC 台式机单根内存条标准数据位宽为 64 位（即 8 字节）； • 因此单通道内存带宽简写为：内存带宽（MB/s） = 等效传输频率（MHz） × 8 字节； • 若开启双通道内存模式，总数据位宽翻倍为 128 位，带宽相应乘以 2。 高频易错陷阱：核心工作频率 vs 等效传输频率 DDR SDRAM 是在时钟信号的上升沿和下降沿均传输数据（双倍速率）；题目中如果给出的是 DDR4-3200，其 3200 是指等效数据传输频率为 3200 MT/s（或等效 3200 MHz），而不是实际核心物理频率（实际核心频率仅为 400 MHz，4 倍预取与双沿传输）；计算带宽时务必使用等效传输频率 3200代入公式！ 考向复习提示：2025–2026 前沿同步：DDR5 普及与 AI 核心显存 HBM3E/HBM4 内存带宽计算题仍以考纲经典的 `DDR3` / `DDR4` 公式为准（务必记住 `64` 位单通道位宽为 `8` 字节）；实际硬件架构已全面迭代至： • DDR5 全面成为主流：消费级与数据中心服务器已广泛采用 `DDR5`（主流起步迈向 `6400 MT/s` 及以上），并配合 `MCRDIMM`、`RDIMM` 提升高并发访存密度； • HBM3E 与 HBM4 高带宽内存：面对大模型千亿参数访存瓶颈，3D 堆叠高带宽内存（`HBM3E`）已成为 AI 加速卡标配；2025–2026 年新一代 `HBM4` 迈入大规模量产商用，接口位宽由 `1024-bit` 翻倍至 `2048-bit`，单栈总带宽跃升至每秒数 TB 级。$kbpars$),(51, $kbpar$[{"t":"list","id":"a1-1-3-4-b1","imp":"normal","items":["1、I/O 操作的特点：","（1）输入和输出任务：I/O 操作也包括辅存与内存之间的数据传输","（2）I/O 操作与 CPU 的运算可同时进行（并行）","（3）多个 I/O 设备的操作也可同时进行工作（并行工作）","（4）每类 I/O 设备都有各自的控制器，它们按照 CPU 的 I/O 操作命令，独立地控制 I/O 操作的全过程。","2、I/O 接口分类：","从数据传输方式：","（1）串行：一次传输 1 位数据；串行的传输速度不一定小于并行的传输速度。（COM 接口，USB、IEEE-1394 口）","（2）并行：一次传输 8 位（或 16 位、32 位）数据。（如 LPT 接口打印机或扫描仪、DVI、HDMI、VGA）","从是否需要能连接多个设备分：","（1）独立式（独占式）：只能外接 1 个设备（DVI、HDMI 等）","（2）共享式（总线式）：可以扩展多个设备（USB 等）。","3、I/O（设备）控制器：","（1）I/O 控制器是用于实现 CPU 对设备的控制部件。","（2）I/O 控制器是控制计算机输入输出的一个最基本的控制系统，可指挥计算机的各个部件按照指令的功能要求协调工作的部件。","（3）由于设备控制器位于 CPU 与设备之间，既要与 CPU 通信，又要与设备通信，还应具有按照 CPU 所发来的命令去控制设备工作的功能。","（4）I/O（设备）控制器的作用：I/O 控制器——负责在 I/O 操作期间对 I/O 设备进行全程控制。","（5）常见 I/O 控制方式：","①、程序直接控制方式（程序查询）：CPU 向 I/O 模块发出读写指令，CPU 会从状态寄存器中读取 I/O 设备的状态，如果是忙碌状态就继续轮询检查状态，如果是已就绪，就代表 I/O 设备已经准备好，可以从中读取数据到 CPU 寄存器中，读到 CPU 后，CPU 还要往存储器（内存）中写入数据，写完后再执行下一套指令。完全采用软件的方式实现。","②、中断驱动方式：中断驱动方式的思想是允许 I/O 设备主动打断 CPU 的运行并请求服务，从而“解放”CPU，使得其向 I/O 控制器发送读命令后可以继续做其他有用的工作。通过程序实现数据传递，但中断处理需要相关硬件的实现。","③、DMA（直接存储方式）：DMA 方式的数据流向是从设备直接放入内存（设备→内存），或者是从内存直接到设备（内存→设备），不再使用 CPU 作为中间者。完全由采用硬件控制数据交换的过程。","④、通道控制方式：通道是一种硬件，可以理解为“低配版的 CPU”。通道与 CPU 相比的话，CPU 能够处理的指令种类比较多，而通道只能执行单一指令。使用这种控制方式，CPU 干涉频率极低，通道会根据 CPU 的指令执行响应程序，只有完成一组数据块的读写后才需要发出中断信号让 CPU 干预。采用软硬件结合的方法，通过执行通道程序（由通道指令组织）控制数据交换的过程。"],"title":"","ordered":false},{"t":"table","id":"a1-1-3-4-t1","imp":"normal","headers":["I/O 控制方式","完成一次读/写的过程","CPU 干预频率","每次 I/O 的数据传输单位","数据流向","优缺点"],"rows":[["程序直接控制方式","CPU 发出 I/O 命令后需要不断轮询","极高","字","设备→CPU→内存；内存→CPU→设备","每一个阶段的优点都是解决了上一阶段的最大缺点。总体来说，整个发展过程就是要尽量减少 CPU 对 I/O 过程的干预，把 CPU 从繁杂的 I/O 控制事务中解脱出来，以便更多地去完成数据处理任务。"],["中断驱动方式","CPU 发出 I/O 命令后可以做其他事，本次 I/O 完成后设备控制器发出中断信号","高","字","设备→CPU→内存；内存→CPU→设备",""],["DMA 方式","CPU 发出 I/O 命令后可以做其他事，本次 I/O 完成后 DMA 控制器发出中断信号","中","块","设备→内存；内存→设备",""],["通道控制方式","CPU 发出 I/O 命令后可以做其他事。通道会执行通道程序以完成 I/O，完成后通道向 CPU 发出中断信号","低","一组块","设备→内存；内存→设备",""]],"title":"四种 I/O 控制方式对比表"},{"t":"list","id":"a1-1-3-4-b2","imp":"normal","items":["4、I/O 总线带宽：","（1）并行总线（PCI、ISA、EISA、AGP 等）","并行总线带宽（MB/s）=并行总线时钟频率（MHz）×并行总线位宽（bit/8=B）×每时钟传输几组数据（cycle）","PCI 总线位宽是 32 位，总线频率 33MHz，每时钟传输 1 组数据，它的带宽为 127.2MB/s，即 1017.6Mbps。","PCI2.1 总线位宽是 64 位，总线频率 66MHz，每时钟传输 1 组数据，它的带宽为 508.6MB/s，即 4068.8Mbps。","AGP 总线位宽是 32 位，总线频率 66MHz，每时钟传输 1 组数据，它的带宽为 254.3MB/s，即 2034.4Mbps。","AGPPro 总线位宽是 32 位，总线频率 66MHz，每时钟传输 1 组数据，它的带宽为 254.3MB/s，即 2034.4Mbps。","AGPPro 是 AGP 的改进型，它使工作站级主板也能利用 AGP 的加速性能，降低了 AGP 所需的电压供应，并没有什么太大的改变。","AGP2X 总线位宽是 32 位，总线频率 66MHz，每时钟传输 2 组数据，它的带宽为 508.6MB/s，即 4068.8Mbps。","AGP4X 总线位宽是 32 位，总线频率 66MHz，每时钟传输 4 组数据，它的带宽为 1017.3MB/s，即 8138.4Mbps。","AGP8X 总线位宽是 32 位，总线频率 66MHz，每时钟传输 8 组数据，它的带宽为 2034.6MB/s，即 16276.8Mbps。","ISA 总线位宽是 16 位，总线频率 8.3MHz，每时钟传输 1 组数据，它的带宽为 15.9MB/s，即 127.2Mbps。","EISA 总线位宽是 32 位，总线频率 8.3MHz，每时钟传输 1 组数据，它的带宽为 31.8MB/s，即 254.4Mbps。","（2）串行总线（PCI-E、USB、IEEE 1394 等）","串行总线带宽（MB/s）=串行总线时钟频率（MHz）×串行总线位宽（bit/8=B）×串行总线管线×编码方式×每时钟传输几组数据（cycle）","PCI Express x16 的带宽为 7629.44MB/s，即 61035.5Mbps。（带宽是 AGP8X 的 3.75 倍。）","注：以下都是理论值，实际上达不到，就像实际网速与带宽一样会有差距。"],"title":"","ordered":false},{"t":"list","id":"a1-1-3-4-b3","imp":"normal","items":["5、PCI 插槽和 PCI-E 插槽（PCI-E x1 和 PCI-E x16）：","一个 PCI Express 连接可以被配置成 x1、x2、x4、x8、x12、x16 和 x32 的数据带宽。x1 的通道能实现单向 312.5MB/秒（2.5Gbit/s×1/8 位）的传输速率，同理 x32 通道连接就能提供 10GB/秒的速率，但考虑使用 8b/10b 编码实际上有 20% 左右的消耗，实际的传输速率大概是 8GB/s（x32 单向）。一般的显卡使用的 PCI-E x16 标准，数据传输率为 4.8GB/s，远远高于现在最流行的 AGP 8X 的 2.1GB/s 的数据流量。","（1）PCI 插槽：","①、工作频率 33MHz；","②、数据线：32 位；","③、传输速率：133MB/s","（2）PCI-E x1 插槽：","①、1 个串行传输通道；","②、最高传输速率：250MB/s","（3）PCI-E x16 插槽：","①、16 个串行传输通道；","②、最高传输速率：5GB/s"],"title":"","ordered":false},{"t":"img","id":"a1-1-3-4-b4","imp":"normal","src":"/kb-assets/theory/p15_r0_269dd9c7cd7a8d1c.png","w":1295,"h":909,"title":"主板上 PCI 插槽、PCI-E x1 插槽与 PCI-E x16 插槽"},{"t":"list","id":"a1-1-3-4-b5","imp":"normal","items":["6、USB 接口：","（1）通用串行总线式接口。","（2）高速、可连接多个设备、串行传输。","（3）传输速率：USB1.1（1.5MB/s）、USB2.0（60MB/s）、USB3.0（625MB/s，5Gbps）、USB3.1（1250MB/s，10Gbps）、USB3.2（2500MB/s，20Gbps）、USB4.0（2500MB/s，20Gbps；5000MB/s，40Gbps）","（4）USB2.0 使用 4（针）线标准连接器；USB3.0 使用 9（针）线标准连接器。","（5）使用“USB 集线器”扩展 USB 接口，最多可连接 127 个设备。","（6）可通过 USB 接口由主机向外设提供电源（+5V，100～500mA）。","（7）USB 支持“即插即用”和“热插拔”。","（8）图标："],"title":"","ordered":false},{"t":"table","id":"a1-1-3-4-t2","imp":"normal","headers":["版本","发布时间","名称","Bits/sec"],"rows":[["USB 3.0","Nov. 2008","SuperSpeed USB 5Gbps","5 Gbps USB 3.2 Gen 1"],["USB 3.1","Jul. 2013","SuperSpeed USB 10Gbps","10 Gbps USB 3.2 Gen 2"],["USB 3.2","Sep. 2017","SuperSpeed USB 20Gbps","20 Gbps USB 3.2 Gen 2x2"],["USB4TM","Sep. 2019","USB4TM 20Gbps","20 Gbps USB4 Gen 2x2"],["USB4TM","Sep. 2019","USB4TM 40Gbps","40 Gbps USB4 Gen 3x2"]],"title":"USB 各版本发布时间与速率对照表"},{"t":"list","id":"a1-1-3-4-b6","imp":"normal","items":["（9）可外接设备：打印机、鼠标、键盘、扫描仪等。","（10）接口类型：TypeA、TypeB、TypeC 等。"],"title":"","ordered":false},{"t":"img","id":"a1-1-3-4-b7","imp":"normal","src":"/kb-assets/theory/p16_r1_70bbe554ecb0604d.png","w":1248,"h":639,"title":"USB 2.0 / USB 3.0 / USB 3.1 常见接口连接器形态与参数对比表"},{"t":"list","id":"a1-1-3-4-b8","imp":"normal","items":["USB 3.2 及以后（包括 USB4）仅支持 Type-C。","（11）使用串口转换工具（器）转串口或并口。","（12）相互兼容的。为了向下兼容 2.0 版，USB 3.0 采用了 9 针脚设计，其中四个针脚和 USB 2.0 的形状、定义均完全相同，而另外 5 根是专门为 USB 3.0 准备的。","7、其他接口：","（1）硬盘常用接口：IDE、SATA（e-SATA）、USB（移动硬盘）等","（2）键盘和鼠标常用接口：USB、PS/2 接口等","（3）网络接口：RJ-45 接口","（4）显示接口：VGA、DVI（24 针）、HDMI（19 针，高清数字音频和视频接口）等","（5）串口 RS232：可以连接鼠标、投影仪等","（6）并口：打印机、扫描仪等。","（7）IEEE-1394 接口：串行方式传输，连接大量数据的音、视频设备，采用 6 线连接器。","8、主板常见接口示例图：","（3）独占式：只能外接1 个设备（DVI、MIDI 等）","（3）组成：指令寄存器IR、程序计数器PC、操作控制器OC。","（4）I/O 控制器的功能：","①、接收 CPU 指令：CPU 的读写指令和参数存储在控制寄存器中","②、向CPU 报告设备的状态：I/O 控制器中会有相应的状态寄存器，用于记录I/O 设备的当前状态。（比如1 代表设备忙碌，0 代表设备就绪）","③、数据交换：数据寄存器，暂存CPU 发来的数据和设备发来的数据，之后将数据发给控制寄存器或CPU。","④、地址识别：类似于内存的地址，为了区分设备控制器中的各个寄存器，需要给各个寄存器设置一个特定的地址。I/O 控制器通过CPU 提供的地址来判断CPU 要读写的是哪个寄存器。","9、I/O 总线及其发展","定义与任务：I/O 总线是计算机用于在 I/O 设备与内存（主机）之间传输数据的部件，由传输线路及控制器组成，主要任务是高速传输数据。","I/O 总线连接的是 I/O 控制器，I/O 控制器提供 I/O 接口，I/O 接口再连接 I/O 设备。","I/O 接口的作用是：连接 I/O 设备自身的控制器，实现 I/O 设备与总线、与主机的连接。","性能指标：I/O 总线最重要的性能指标是带宽，即单位时间内可传输的最大数据量。","【新增计算真题】若某计算机数据总线宽度为 `64 位`，工作频率为 `133MHz`，每个总线周期传输 `2` 次数据，则该总线带宽为：`C. 2.128 GB/s`（选项：`A. 1.064 GB/s`、`B. 1.064 Gb/s`、`C. 2.128 GB/s`、`D. 2.128 Gb/s`）。","带宽解析与易错单位：`带宽 = 133 MHz * (64 bit / 8) * 2 = 2128 MB/s = 2.128 GB/s`（按十进制总线速率换算 `1 GB/s = 1000 MB/s`）；注意区分大写的 `GB/s`（字节每秒） 与小写的 `Gb/s`（比特每秒），二者相差 `8` 倍（`2.128 GB/s = 17.024 Gb/s`）！","PCI Express x1 总线位宽是1 位，总线频率2500MHz，串行总线管线是1 条，每时钟传输2 组数据，编码方式为8b/10b，它的带宽为476.84MB/s，即3814.7Mbps。（带宽是PCI 的3.75 倍）","公式是2500000000(Hz)*1/8(bit)*1(条管线)*8/10(bit)*2(每时钟传输2 组数据)=500000000B/s=476.8371582MB/s，即3814.6972656Mbps。","PCI Expressx2 的带宽为953.68MB/s，即7629.4Mbps。（此模式仅用于主板内部接口而非插槽模式）","PCI Expressx4 的带宽为1907.36MB/s，即15258.9Mbps。","PCI Expressx8 的带宽为3814.72MB/s，即30517.8Mbps。","PCI Expressx32 的带宽为15258.88MB/s，即122071Mbps。","10、主机、外围设备与总线：计算机的主机：CPU、内存储器、总线等。 计算机的外围设备：外存储器、输入设备、输出设备。","（1）总线：提供各部件之间相互交换各种信息的通道。 总线按连接方式分为：前端总线（CPU 总线），连接内存和 CPU；I/O 总线（PCI 总线），连接内存与 I/O 设备。 总线传输的内容（信号）：数据信号、地址信号、控制信号。","（11）可通过串口转换器转为串口或并口；USB 3.2 及以后标准（含 USB4）仅支持 Type-C 接口（支持正反盲插）。"],"title":"","ordered":false},{"t":"img","id":"a1-1-3-4-b9","imp":"normal","src":"/kb-assets/theory/p17_r0_b99e11f30731a9b3.png","w":1518,"h":907,"title":"主板背部常见外设接口实景标注图"},{"t":"callout","id":"a1-1-3-4-b11","imp":"core","kind":"tip","text":"主机与外设通信方式：==程序查询方式（CPU 全程等待效率最低）==、==中断方式（外设就绪打断 CPU）==、==DMA 方式（直接内存访问，外设与主存成批交换数据无需 CPU 介入）==；常用总线接口包括 PCI-Express（主板内部高速点对点）、USB（热插拔串行）、SATA（硬盘串行接口）。","title":"考向复习提示：I/O 操作方式及常用外部总线"},{"t":"callout","id":"a1-1-3-4-b12","imp":"core","kind":"trap","text":"专转本必考趋势：传统早期采用并行接口（如打印机并口 LPT、IDE 硬盘并口）；由于高频时并行多引脚间存在严重的电磁串扰与时钟偏移，==现代高速接口全面转向采用差分信号的高速串行接口（如 PCI-E、SATA、USB、雷电）==；常考判断题误以为“并行传输速率一定快于串行”，结论完全错误！","title":"高频易错陷阱：串行接口 vs 并行接口发展趋势"},{"t":"callout","id":"a1-1-3-4-p2-sync-tip","imp":"core","kind":"tip","text":"高速串行总线取代并行总线的产业趋势持续加速（考试中仍重记 `PCI-E` / `USB 3.x` / `SATA` 串行原理）：\n• ==USB4 Version 2.0 与 Thunderbolt 5（雷电 5）==：引入全新 `PAM3` 三电平调制技术，实现 `80 Gbps` 对称双向带宽与非对称显示增强最高 `120 Gbps` 速率（向下兼容 `Type-C`）；英特尔雷电 5 认证还强制保障 `64 Gbps` PCIe 吞吐及最高 `240W` 供电；\n• ==PCIe 5.0 / 6.0 / 7.0 演进==：`PCIe 5.0`（`32 GT/s`）已在旗舰显卡与高速固态硬盘广泛商用；`PCIe 6.0`（`PAM4` 调制，`64 GT/s`，x16 双向约 `256 GB/s`）逐步落地 AI 服务器；`PCIe 7.0`（`128 GT/s`，x16 双向达 `512 GB/s`）规范亦已正式发布。","title":"考向复习提示：2025–2026 前沿同步：USB4 v2.0、Thunderbolt 5 与 PCIe 6.0/7.0"}]$kbpar$::jsonb, $kbpars$1、I/O 操作的特点： （1）输入和输出任务：I/O 操作也包括辅存与内存之间的数据传输 （2）I/O 操作与 CPU 的运算可同时进行（并行） （3）多个 I/O 设备的操作也可同时进行工作（并行工作） （4）每类 I/O 设备都有各自的控制器，它们按照 CPU 的 I/O 操作命令，独立地控制 I/O 操作的全过程。 2、I/O 接口分类： 从数据传输方式： （1）串行：一次传输 1 位数据；串行的传输速度不一定小于并行的传输速度。（COM 接口，USB、IEEE-1394 口） （2）并行：一次传输 8 位（或 16 位、32 位）数据。（如 LPT 接口打印机或扫描仪、DVI、HDMI、VGA） 从是否需要能连接多个设备分： （1）独立式（独占式）：只能外接 1 个设备（DVI、HDMI 等） （2）共享式（总线式）：可以扩展多个设备（USB 等）。 3、I/O（设备）控制器： （1）I/O 控制器是用于实现 CPU 对设备的控制部件。 （2）I/O 控制器是控制计算机输入输出的一个最基本的控制系统，可指挥计算机的各个部件按照指令的功能要求协调工作的部件。 （3）由于设备控制器位于 CPU 与设备之间，既要与 CPU 通信，又要与设备通信，还应具有按照 CPU 所发来的命令去控制设备工作的功能。 （4）I/O（设备）控制器的作用：I/O 控制器——负责在 I/O 操作期间对 I/O 设备进行全程控制。 （5）常见 I/O 控制方式： ①、程序直接控制方式（程序查询）：CPU 向 I/O 模块发出读写指令，CPU 会从状态寄存器中读取 I/O 设备的状态，如果是忙碌状态就继续轮询检查状态，如果是已就绪，就代表 I/O 设备已经准备好，可以从中读取数据到 CPU 寄存器中，读到 CPU 后，CPU 还要往存储器（内存）中写入数据，写完后再执行下一套指令。完全采用软件的方式实现。 ②、中断驱动方式：中断驱动方式的思想是允许 I/O 设备主动打断 CPU 的运行并请求服务，从而“解放”CPU，使得其向 I/O 控制器发送读命令后可以继续做其他有用的工作。通过程序实现数据传递，但中断处理需要相关硬件的实现。 ③、DMA（直接存储方式）：DMA 方式的数据流向是从设备直接放入内存（设备→内存），或者是从内存直接到设备（内存→设备），不再使用 CPU 作为中间者。完全由采用硬件控制数据交换的过程。 ④、通道控制方式：通道是一种硬件，可以理解为“低配版的 CPU”。通道与 CPU 相比的话，CPU 能够处理的指令种类比较多，而通道只能执行单一指令。使用这种控制方式，CPU 干涉频率极低，通道会根据 CPU 的指令执行响应程序，只有完成一组数据块的读写后才需要发出中断信号让 CPU 干预。采用软硬件结合的方法，通过执行通道程序（由通道指令组织）控制数据交换的过程。 程序直接控制方式 CPU 发出 I/O 命令后需要不断轮询 极高 字 设备→CPU→内存；内存→CPU→设备 每一个阶段的优点都是解决了上一阶段的最大缺点。总体来说，整个发展过程就是要尽量减少 CPU 对 I/O 过程的干预，把 CPU 从繁杂的 I/O 控制事务中解脱出来，以便更多地去完成数据处理任务。 中断驱动方式 CPU 发出 I/O 命令后可以做其他事，本次 I/O 完成后设备控制器发出中断信号 高 字 设备→CPU→内存；内存→CPU→设备 DMA 方式 CPU 发出 I/O 命令后可以做其他事，本次 I/O 完成后 DMA 控制器发出中断信号 中 块 设备→内存；内存→设备 通道控制方式 CPU 发出 I/O 命令后可以做其他事。通道会执行通道程序以完成 I/O，完成后通道向 CPU 发出中断信号 低 一组块 设备→内存；内存→设备 4、I/O 总线带宽： （1）并行总线（PCI、ISA、EISA、AGP 等） 并行总线带宽（MB/s）=并行总线时钟频率（MHz）×并行总线位宽（bit/8=B）×每时钟传输几组数据（cycle） PCI 总线位宽是 32 位，总线频率 33MHz，每时钟传输 1 组数据，它的带宽为 127.2MB/s，即 1017.6Mbps。 PCI2.1 总线位宽是 64 位，总线频率 66MHz，每时钟传输 1 组数据，它的带宽为 508.6MB/s，即 4068.8Mbps。 AGP 总线位宽是 32 位，总线频率 66MHz，每时钟传输 1 组数据，它的带宽为 254.3MB/s，即 2034.4Mbps。 AGPPro 总线位宽是 32 位，总线频率 66MHz，每时钟传输 1 组数据，它的带宽为 254.3MB/s，即 2034.4Mbps。 AGPPro 是 AGP 的改进型，它使工作站级主板也能利用 AGP 的加速性能，降低了 AGP 所需的电压供应，并没有什么太大的改变。 AGP2X 总线位宽是 32 位，总线频率 66MHz，每时钟传输 2 组数据，它的带宽为 508.6MB/s，即 4068.8Mbps。 AGP4X 总线位宽是 32 位，总线频率 66MHz，每时钟传输 4 组数据，它的带宽为 1017.3MB/s，即 8138.4Mbps。 AGP8X 总线位宽是 32 位，总线频率 66MHz，每时钟传输 8 组数据，它的带宽为 2034.6MB/s，即 16276.8Mbps。 ISA 总线位宽是 16 位，总线频率 8.3MHz，每时钟传输 1 组数据，它的带宽为 15.9MB/s，即 127.2Mbps。 EISA 总线位宽是 32 位，总线频率 8.3MHz，每时钟传输 1 组数据，它的带宽为 31.8MB/s，即 254.4Mbps。 （2）串行总线（PCI-E、USB、IEEE 1394 等） 串行总线带宽（MB/s）=串行总线时钟频率（MHz）×串行总线位宽（bit/8=B）×串行总线管线×编码方式×每时钟传输几组数据（cycle） PCI Express x16 的带宽为 7629.44MB/s，即 61035.5Mbps。（带宽是 AGP8X 的 3.75 倍。） 注：以下都是理论值，实际上达不到，就像实际网速与带宽一样会有差距。 5、PCI 插槽和 PCI-E 插槽（PCI-E x1 和 PCI-E x16）： 一个 PCI Express 连接可以被配置成 x1、x2、x4、x8、x12、x16 和 x32 的数据带宽。x1 的通道能实现单向 312.5MB/秒（2.5Gbit/s×1/8 位）的传输速率，同理 x32 通道连接就能提供 10GB/秒的速率，但考虑使用 8b/10b 编码实际上有 20% 左右的消耗，实际的传输速率大概是 8GB/s（x32 单向）。一般的显卡使用的 PCI-E x16 标准，数据传输率为 4.8GB/s，远远高于现在最流行的 AGP 8X 的 2.1GB/s 的数据流量。 （1）PCI 插槽： ①、工作频率 33MHz； ②、数据线：32 位； ③、传输速率：133MB/s （2）PCI-E x1 插槽： ①、1 个串行传输通道； ②、最高传输速率：250MB/s （3）PCI-E x16 插槽： ①、16 个串行传输通道； ②、最高传输速率：5GB/s 6、USB 接口： （1）通用串行总线式接口。 （2）高速、可连接多个设备、串行传输。 （3）传输速率：USB1.1（1.5MB/s）、USB2.0（60MB/s）、USB3.0（625MB/s，5Gbps）、USB3.1（1250MB/s，10Gbps）、USB3.2（2500MB/s，20Gbps）、USB4.0（2500MB/s，20Gbps；5000MB/s，40Gbps） （4）USB2.0 使用 4（针）线标准连接器；USB3.0 使用 9（针）线标准连接器。 （5）使用“USB 集线器”扩展 USB 接口，最多可连接 127 个设备。 （6）可通过 USB 接口由主机向外设提供电源（+5V，100～500mA）。 （7）USB 支持“即插即用”和“热插拔”。 （8）图标： USB 3.0 Nov. 2008 SuperSpeed USB 5Gbps 5 Gbps USB 3.2 Gen 1 USB 3.1 Jul. 2013 SuperSpeed USB 10Gbps 10 Gbps USB 3.2 Gen 2 USB 3.2 Sep. 2017 SuperSpeed USB 20Gbps 20 Gbps USB 3.2 Gen 2x2 USB4TM Sep. 2019 USB4TM 20Gbps 20 Gbps USB4 Gen 2x2 USB4TM Sep. 2019 USB4TM 40Gbps 40 Gbps USB4 Gen 3x2 （9）可外接设备：打印机、鼠标、键盘、扫描仪等。 （10）接口类型：TypeA、TypeB、TypeC 等。 USB 3.2 及以后（包括 USB4）仅支持 Type-C。 （11）使用串口转换工具（器）转串口或并口。 （12）相互兼容的。为了向下兼容 2.0 版，USB 3.0 采用了 9 针脚设计，其中四个针脚和 USB 2.0 的形状、定义均完全相同，而另外 5 根是专门为 USB 3.0 准备的。 7、其他接口： （1）硬盘常用接口：IDE、SATA（e-SATA）、USB（移动硬盘）等 （2）键盘和鼠标常用接口：USB、PS/2 接口等 （3）网络接口：RJ-45 接口 （4）显示接口：VGA、DVI（24 针）、HDMI（19 针，高清数字音频和视频接口）等 （5）串口 RS232：可以连接鼠标、投影仪等 （6）并口：打印机、扫描仪等。 （7）IEEE-1394 接口：串行方式传输，连接大量数据的音、视频设备，采用 6 线连接器。 8、主板常见接口示例图： （3）独占式：只能外接1 个设备（DVI、MIDI 等） （3）组成：指令寄存器IR、程序计数器PC、操作控制器OC。 （4）I/O 控制器的功能： ①、接收 CPU 指令：CPU 的读写指令和参数存储在控制寄存器中 ②、向CPU 报告设备的状态：I/O 控制器中会有相应的状态寄存器，用于记录I/O 设备的当前状态。（比如1 代表设备忙碌，0 代表设备就绪） ③、数据交换：数据寄存器，暂存CPU 发来的数据和设备发来的数据，之后将数据发给控制寄存器或CPU。 ④、地址识别：类似于内存的地址，为了区分设备控制器中的各个寄存器，需要给各个寄存器设置一个特定的地址。I/O 控制器通过CPU 提供的地址来判断CPU 要读写的是哪个寄存器。 9、I/O 总线及其发展 定义与任务：I/O 总线是计算机用于在 I/O 设备与内存（主机）之间传输数据的部件，由传输线路及控制器组成，主要任务是高速传输数据。 I/O 总线连接的是 I/O 控制器，I/O 控制器提供 I/O 接口，I/O 接口再连接 I/O 设备。 I/O 接口的作用是：连接 I/O 设备自身的控制器，实现 I/O 设备与总线、与主机的连接。 性能指标：I/O 总线最重要的性能指标是带宽，即单位时间内可传输的最大数据量。 【新增计算真题】若某计算机数据总线宽度为 `64 位`，工作频率为 `133MHz`，每个总线周期传输 `2` 次数据，则该总线带宽为：`C. 2.128 GB/s`（选项：`A. 1.064 GB/s`、`B. 1.064 Gb/s`、`C. 2.128 GB/s`、`D. 2.128 Gb/s`）。 带宽解析与易错单位：`带宽 = 133 MHz * (64 bit / 8) * 2 = 2128 MB/s = 2.128 GB/s`（按十进制总线速率换算 `1 GB/s = 1000 MB/s`）；注意区分大写的 `GB/s`（字节每秒） 与小写的 `Gb/s`（比特每秒），二者相差 `8` 倍（`2.128 GB/s = 17.024 Gb/s`）！ PCI Express x1 总线位宽是1 位，总线频率2500MHz，串行总线管线是1 条，每时钟传输2 组数据，编码方式为8b/10b，它的带宽为476.84MB/s，即3814.7Mbps。（带宽是PCI 的3.75 倍） 公式是2500000000(Hz)*1/8(bit)*1(条管线)*8/10(bit)*2(每时钟传输2 组数据)=500000000B/s=476.8371582MB/s，即3814.6972656Mbps。 PCI Expressx2 的带宽为953.68MB/s，即7629.4Mbps。（此模式仅用于主板内部接口而非插槽模式） PCI Expressx4 的带宽为1907.36MB/s，即15258.9Mbps。 PCI Expressx8 的带宽为3814.72MB/s，即30517.8Mbps。 PCI Expressx32 的带宽为15258.88MB/s，即122071Mbps。 10、主机、外围设备与总线：计算机的主机：CPU、内存储器、总线等。 计算机的外围设备：外存储器、输入设备、输出设备。 （1）总线：提供各部件之间相互交换各种信息的通道。 总线按连接方式分为：前端总线（CPU 总线），连接内存和 CPU；I/O 总线（PCI 总线），连接内存与 I/O 设备。 总线传输的内容（信号）：数据信号、地址信号、控制信号。 （11）可通过串口转换器转为串口或并口；USB 3.2 及以后标准（含 USB4）仅支持 Type-C 接口（支持正反盲插）。 考向复习提示：I/O 操作方式及常用外部总线 主机与外设通信方式：程序查询方式（CPU 全程等待效率最低）、中断方式（外设就绪打断 CPU）、DMA 方式（直接内存访问，外设与主存成批交换数据无需 CPU 介入）；常用总线接口包括 PCI-Express（主板内部高速点对点）、USB（热插拔串行）、SATA（硬盘串行接口）。 高频易错陷阱：串行接口 vs 并行接口发展趋势 专转本必考趋势：传统早期采用并行接口（如打印机并口 LPT、IDE 硬盘并口）；由于高频时并行多引脚间存在严重的电磁串扰与时钟偏移，现代高速接口全面转向采用差分信号的高速串行接口（如 PCI-E、SATA、USB、雷电）；常考判断题误以为“并行传输速率一定快于串行”，结论完全错误！ 考向复习提示：2025–2026 前沿同步：USB4 v2.0、Thunderbolt 5 与 PCIe 6.0/7.0 高速串行总线取代并行总线的产业趋势持续加速（考试中仍重记 `PCI-E` / `USB 3.x` / `SATA` 串行原理）： • USB4 Version 2.0 与 Thunderbolt 5（雷电 5）：引入全新 `PAM3` 三电平调制技术，实现 `80 Gbps` 对称双向带宽与非对称显示增强最高 `120 Gbps` 速率（向下兼容 `Type-C`）；英特尔雷电 5 认证还强制保障 `64 Gbps` PCIe 吞吐及最高 `240W` 供电； • PCIe 5.0 / 6.0 / 7.0 演进：`PCIe 5.0`（`32 GT/s`）已在旗舰显卡与高速固态硬盘广泛商用；`PCIe 6.0`（`PAM4` 调制，`64 GT/s`，x16 双向约 `256 GB/s`）逐步落地 AI 服务器；`PCIe 7.0`（`128 GT/s`，x16 双向达 `512 GB/s`）规范亦已正式发布。$kbpars$);
do $$
declare r record; o record; v integer;
begin
  for r in select node_id, blocks, search_text from _kbpar order by node_id loop
    select rev_no, html, source_ref into o from kb_revision
     where node_id = r.node_id and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 无已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v, r.blocks, o.html, r.search_text, o.source_ref);
    update kb_entry set published_rev = v, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
